def frame(*, fields, sequence):
    escapes = {"\\": "\\\\", ";": "\\;", "\r": "\\r", "\n": "\\n"}
    digits = []
    number = sequence
    while number:
        number, digit = divmod(number, 10)
        digits.append("0123456789"[digit])
    header = "".join(reversed(digits)) or "0"
    parts = [header, "|"]
    for field in fields:
        escaped = "".join(escapes.get(char, char) for char in field)
        parts.extend((str(len(escaped.encode("utf-8"))), ":", escaped, ";"))
    parts.append("\r\n")
    return "".join(parts)
